// Calculate date range for the past 7 days
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

// ISO strings for GitHub API queries
const since = sevenDaysAgo.toISOString();
const until = now.toISOString();

// Human-friendly week label
const weekLabel = sevenDaysAgo.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
  + ' \u2013 ' + now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

return [{
  ...$json,
  since,
  until,
  sinceDate: sevenDaysAgo.toISOString().split('T')[0],
  untilDate: now.toISOString().split('T')[0],
  weekLabel
}];

// Collapse all commit items into a single item with a 'commits' array
// Preserve the original config context from the upstream node

const originalCtx = $("Compute Date Range").first().json;
const allItems = $input.all();

// Extract commit data from each item
const commits = allItems.map(item => {
  const c = item.json.commit || {};
  return {
    sha: item.json.sha ? item.json.sha.substring(0, 7) : 'N/A',
    message: (c.message || 'N/A').split('\n')[0],
    author: c.author ? c.author.name : (c.committer ? c.committer.name : 'N/A'),
    date: c.author ? c.author.date : (c.committer ? c.committer.date : null),
    url: item.json.html_url || ''
  };
});

return [{
  ...originalCtx,
  _source: 'commits',
  commits
}];

// Collapse all issue items into a single item with an 'issues' array
// Filter out pull requests (GitHub Issues API returns both)

const originalCtx = $("Compute Date Range").first().json;
const allItems = $input.all();

const issues = allItems
  .filter(item => !item.json.pull_request) // Remove PRs from issues list
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    author: item.json.user ? item.json.user.login : 'N/A',
    state: item.json.state,
    closed_at: item.json.closed_at,
    labels: item.json.labels ? item.json.labels.map(l => l.name) : [],
    url: item.json.html_url || ''
  }));

return [{
  ...originalCtx,
  _source: 'issues',
  issues
}];

// Collapse all PR items into a single item with a 'prs' array
// Only keep PRs that were merged within our date range

const originalCtx = $("Compute Date Range").first().json;
const allItems = $input.all();

// Use the 'since' date to filter merged_at
const sinceDate = new Date(originalCtx.since);

const prs = allItems
  .filter(item => item.json.merged_at && new Date(item.json.merged_at) >= sinceDate)
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    author: item.json.user ? item.json.user.login : 'N/A',
    merged_at: item.json.merged_at,
    additions: item.json.additions || 0,
    deletions: item.json.deletions || 0,
    labels: item.json.labels ? item.json.labels.map(l => l.name) : [],
    url: item.json.html_url || ''
  }));

return [{
  ...originalCtx,
  _source: 'prs',
  prs
}];

// The Merge node (multiplex) gives us a single item with keys:
// 0 = Clean Commits output, 1 = Clean Issues output, 2 = Clean PRs output
// Extract and combine them into one summary.

const commitsData = $json["0"] || {};
const issuesData = $json["1"] || {};
const prsData = $json["2"] || {};

const repo = commitsData.githubRepo || issuesData.githubRepo || prsData.githubRepo || 'unknown';
const weekLabel = commitsData.weekLabel || issuesData.weekLabel || prsData.weekLabel || '';
const lang = commitsData.language || issuesData.language || prsData.language || 'EN';

const commits = commitsData.commits || [];
const issues = issuesData.issues || [];
const prs = prsData.prs || [];

// Compute unique authors
const allAuthors = new Set();
commits.forEach(c => { if (c.author) allAuthors.add(c.author); });
issues.forEach(i => { if (i.author) allAuthors.add('@' + i.author); });
prs.forEach(p => { if (p.author) allAuthors.add('@' + p.author); });

const uniqueContributors = allAuthors.size;

// Build formatted lists for the prompt (limit to 30 each)
const commitLines = commits.slice(0, 30).map(c =>
  `- [\`${c.sha}\`] ${c.message} (${c.author})`
).join('\n');

const issueLines = issues.slice(0, 30).map(i =>
  `- #${i.number}: ${i.title} (by @${i.author})${i.labels.length ? ' [' + i.labels.join(', ') + ']' : ''}`
).join('\n');

const prLines = prs.slice(0, 30).map(p =>
  `- #${p.number}: ${p.title} (by @${p.author}) [+${p.additions}/-${p.deletions}]${p.labels.length ? ' [' + p.labels.join(', ') + ']' : ''}`
).join('\n');

// Detect errors from upstream
const hasErrors =
  commits.length === 0 && Object.keys(commitsData).length > 0
  || (commitsData.error || issuesData.error || prsData.error);

// Build system prompt and user message based on language
let systemPrompt, userMessage;

if (lang === 'FR') {
  systemPrompt = 'Vous êtes un assistant qui génère des résumés hebdomadaires de développement pour des d\u00e9p\u00f4ts GitHub. R\u00e9pondez en fran\u00e7ais, de mani\u00e8re claire et professionnelle.';
  userMessage = `G\u00e9n\u00e8re un r\u00e9sum\u00e9 narratif de la semaine de d\u00e9veloppement pour le d\u00e9p\u00f4t GitHub **${repo}**.

P\u00e9riode : ${weekLabel}

**Aper\u00e7u g\u00e9n\u00e9ral :**
- Commits : ${commits.length}
- Issues ferm\u00e9es : ${issues.length}
- PRs fusionn\u00e9es : ${prs.length}
- Contributeurs uniques : ${uniqueContributors}

**Commits (${commits.length}) :**
${commitLines || '(aucun commit cette semaine)'}

**Issues ferm\u00e9es (${issues.length}) :**
${issueLines || '(aucune issue ferm\u00e9e cette semaine)'}

**PRs fusionn\u00e9es (${prs.length}) :**
${prLines || '(aucune PR fusionn\u00e9e cette semaine)'}

R\u00e9dige le r\u00e9sum\u00e9 de mani\u00e8re lisible avec des sections claires. Inclus les tendances, les points forts, les faits marquants et toute observation pertinente. Termine par un message de cl\u00f4ture engageant pour l'\u00e9quipe.`;
} else {
  systemPrompt = 'You are an assistant that generates weekly development summaries for GitHub repositories. Respond in English, in a clear and professional tone.';
  userMessage = `Generate a narrative weekly development summary for GitHub repository **${repo}**.

Period: ${weekLabel}

**Overview:**
- Commits: ${commits.length}
- Closed Issues: ${issues.length}
- Merged PRs: ${prs.length}
- Unique Contributors: ${uniqueContributors}

**Commits (${commits.length}):**
${commitLines || '(no commits this week)'}

**Closed Issues (${issues.length}):**
${issueLines || '(no closed issues this week)'}

**Merged PRs (${prs.length}):**
${prLines || '(no merged PRs this week)'}

Write the summary in a readable format with clear sections. Include trends, highlights, noteworthy changes, and any relevant observations. End with an engaging sign-off message for the team.`;
}

return [{
  repo,
  weekLabel,
  language: lang,
  destinationChannel: commitsData.destinationChannel || issuesData.destinationChannel || prsData.destinationChannel || '',
  stats: {
    totalCommits: commits.length,
    totalIssues: issues.length,
    totalPRs: prs.length,
    uniqueContributors
  },
  commits,
  issues,
  prs,
  systemPrompt,
  userMessage,
  hasErrors
}];

// Format the final message from Claude's response
const claudeResponse = $("Claude API - Generate Summary").first();

const s = $json.stats || {};
const repo = $json.repo || 'unknown';
const weekLabel = $json.weekLabel || '';
const dest = $json.destinationChannel || '';

let finalMessage = '';

// Check if Claude returned an error or empty response
const claudeError = claudeResponse.json.error || !claudeResponse.json.content;
const claudeText = (!claudeError && claudeResponse.json.content)
  ? claudeResponse.json.content[0].text
  : null;

if (claudeError || !claudeText) {
  // Fallback: stats-only summary
  finalMessage = `:warning: *Weekly Dev Summary - ${repo}* :warning:\n\n`;
  finalMessage += `*Week:* ${weekLabel}\n\n`;
  finalMessage += `*Stats:* ${s.totalCommits || 0} commits, ${s.totalIssues || 0} issues closed, ${s.totalPRs || 0} PRs merged, ${s.uniqueContributors || 0} contributors\n\n`;

  if ($json.prs && $json.prs.length > 0) {
    finalMessage += `*Merged PRs:*\n`;
    $json.prs.slice(0, 10).forEach(pr => {
      finalMessage += `  #${pr.number} - ${pr.title} (by @${pr.author})\n`;
    });
    finalMessage += '\n';
  }

  if ($json.commits && $json.commits.length > 0) {
    finalMessage += `*Top Commits:*\n`;
    $json.commits.slice(0, 10).forEach(c => {
      finalMessage += `  \`${c.sha}\` - ${c.message} (${c.author})\n`;
    });
    finalMessage += '\n';
  }

  finalMessage += `:robot: _Claude AI summary unavailable \u2014 fallback stats shown._`;
} else {
  // Claude generated a narrative summary
  finalMessage = `:spiral_calendar: *Weekly Dev Summary \u2014 ${repo}*\n`;
  finalMessage += `*Week:* ${weekLabel}\n`;
  finalMessage += `*Stats:* ${s.totalCommits || 0} commits \u00b7 ${s.totalIssues || 0} issues \u00b7 ${s.totalPRs || 0} PRs \u00b7 ${s.uniqueContributors || 0} contributors\n\n`;
  finalMessage += claudeText;
}

// Append footer
finalMessage += `\n\n---\n_G\u00e9n\u00e9r\u00e9 par le workflow Weekly Dev Summary_ :robot_face:`;

return [{
  message: finalMessage,
  destination: dest,
  repo,
  weekLabel,
  stats: s
}];
